export function trails () {
 let context = this.context
 let page = context.page
 let result = page.story
  .filter(item => item.type == "paragraph")
  .map(item => item.text)
  .filter(text => text.startsWith('[['))
  .map((text,i) => ({
   name:`trail ${i+1}`,   
   graph: trail(text.split(/ . /))
  }))
 this.aspect = [{
  id:context.itemId,
  source:page.title,
  result}]
 this.items = [{
  type: "solo",
  text: "LINEUP\nINCLUDED",
  aspects: result
 },'See [[Solo Lineup Browser]]']
 return `${result.length} aspects`
}

function trail(names) {
 let graph = new Graph()
 let prev = null
 for (let each of names) {
  let name = each
   .replaceAll(/[\[\]]/g,"")
   .replaceAll(/ +/g,"\n")
  let nid = graph.addNode("",{name})
  if(prev !== null) graph.addRel("Trail",prev,nid,{})
  prev = nid
 }
 return graph
}

